// Problem RFC 9457 problem details with a stable `code`.
type Problem struct {
	// Code Stable machine-readable identifier, for example `not_found`, `validation_failed`, `not_ready`.
	//
	// Examples: not_found
	Code string `json:"code"`

	// Detail Human-readable explanation for this occurrence. Never contains secrets.
	Detail *string `json:"detail,omitempty"`

	// Errors Field errors for `validation_failed`.
	Errors *[]FieldError `json:"errors,omitempty"`

	// Extensions Whole-number details of a limit problem: `limitMinutes` and `usedMinutes` for `watch_limit_reached`,
	// `maxStreams` and `activeStreams` for `stream_limit_reached`. Absent for other problems.
	//
	//
	// Examples: {"activeStreams":1,"maxStreams":1}
	Extensions *map[string]int `json:"extensions,omitempty"`

	// Instance Request path that produced the problem.
	Instance *string `json:"instance,omitempty"`

	// RetryAfterSeconds Remaining lock in seconds for `pin_locked` (same value as `Retry-After`).
	RetryAfterSeconds *int `json:"retryAfterSeconds,omitempty"`

	// Status HTTP status code of this response.
	Status int `json:"status"`

	// Title Short human-readable summary, English, stable per `code`.
	Title string `json:"title"`

	// Type URI reference identifying the problem type; `about:blank` for generic HTTP errors.
	//
	// Examples: about:blank
	Type string `json:"type"`
}

